export default JSON.parse("{\"id\":\"interpersonal_effectiveness_handout_6\",\"module\":\"Interpersonal Effectiveness\",\"module_category\":\"Interpersonal Effectiveness Skills\",\"item_type\":\"handout\",\"item_number\":\"6\",\"title\":\"Guidelines for Relationship Effectiveness: Keeping the Relationship (GIVE) A way to remember these skills is to remember the word GIVE (DEAR MAN, GIVE): (Be) Gentle\",\"source_marker\":\"Interpersonal Effectiveness Handout 6   (I. E. Worksheets 4, 5)\",\"source_pdf\":\"DBT Skills Workbook.pdf\",\"source_pdf_pages\":[152],\"source_book_pages\":[\"128\"],\"related_references\":[\"I. E. Worksheets 4, 5\"],\"is_example\":false,\"fillable_html_created\":false,\"keywords\":[\"DEAR\",\"Effectiveness\",\"GIVE\",\"Gentle\",\"Guidelines\",\"Keeping\",\"Relationship\",\"remember\",\"skills\",\"these\",\"word\"],\"pages\":[{\"pdf_page\":152,\"book_page\":\"128\",\"text\":\"128\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\n\u00ab\\nInterpersonal Effectiveness Handout 6   (I. E. Worksheets 4, 5)\\nGuidelines for Relationship Effectiveness:\\nKeeping\u00a0the\u00a0Relationship (GIVE)\\nA way to remember these skills is to remember the word GIVE (DEAR MAN, GIVE):\\n(Be) Gentle\\n(Act) Interested\\nValidate\\n(Use an) Easy manner\\n(Be)Gentle\\nBe nice and respectful.\\nNo attacks:\\nNo verbal or physical attacks. No hitting, clenching fists. No harassment of any\\nkind. Express anger directly with words.\\nNo threats:\\nIf you have to describe painful consequences for not getting what you want,\\ndescribe them calmly and without exaggerating.\\nNo \u201cmanipulative\u201d statements, no hidden threats. No \u201cI\u2019ll kill myself if you .\u00a0.\u00a0. \u201d\\nTolerate a \u201cno.\u201d Stay in the discussion even if it gets painful. Exit gracefully.\\nNo judging:\\nNo moralizing. No \u201cIf you were a good person, you would .\u00a0.\u00a0. \u201d\\nNo \u201cYou should\u00a0.\u00a0.\u00a0. \u201d or \u201cYou shouldn\u2019t .\u00a0.\u00a0. \u201d Abandon blame.\\nNo sneering: No smirking, eye rolling, sucking teeth. No cutting off or walking away.\\nNo saying, \u201cThat\u2019s stupid, don\u2019t be sad,\u201d \u201cI don\u2019t care what you say.\u201d\\n(Act)Interested\\nListen and appear interested in the other person.\\nListen to the other person\u2019s point of view.\\nFace the person; maintain eye contact; lean toward the person rather than\\naway. Don\u2019t interrupt or talk over the person.\\nBe sensitive to the person\u2019s wish to have the discussion at a later time. Be\\npatient.\\nValidate\\nWith words and actions, show that you understand the other person\u2019s\\nfeelings and thoughts about the situation. See the world from the other person\u2019s\\npoint of view, and then say or act on what you see.\\n\u201cI realize this is hard for you, and .\u00a0.\u00a0. \u201d, \u201cI see that you are busy, and .\u00a0.\u00a0. \u201d\\nGo to a private place when the person is uncomfortable talking in a public\\nplace.\\n(Use an)\\nEasy manner\\nUse a little humor.\\nSmile. Ease the person along. Be light-hearted. Sweet-talk.\\nUse a \u201csoft sell\u201d over a \u201chard sell.\u201d Be \u201cpolitical.\u201d\\nLeave your attitude at the door.\\nOther ideas:\"}],\"full_text\":\"\u00ab\\nInterpersonal Effectiveness Handout 6   (I. E. Worksheets 4, 5)\\nGuidelines for Relationship Effectiveness:\\nKeeping\u00a0the\u00a0Relationship (GIVE)\\nA way to remember these skills is to remember the word GIVE (DEAR MAN, GIVE):\\n(Be) Gentle\\n(Act) Interested\\nValidate\\n(Use an) Easy manner\\n(Be)Gentle\\nBe nice and respectful.\\nNo attacks:\\nNo verbal or physical attacks. No hitting, clenching fists. No harassment of any\\nkind. Express anger directly with words.\\nNo threats:\\nIf you have to describe painful consequences for not getting what you want,\\ndescribe them calmly and without exaggerating.\\nNo \u201cmanipulative\u201d statements, no hidden threats. No \u201cI\u2019ll kill myself if you .\u00a0.\u00a0. \u201d\\nTolerate a \u201cno.\u201d Stay in the discussion even if it gets painful. Exit gracefully.\\nNo judging:\\nNo moralizing. No \u201cIf you were a good person, you would .\u00a0.\u00a0. \u201d\\nNo \u201cYou should\u00a0.\u00a0.\u00a0. \u201d or \u201cYou shouldn\u2019t .\u00a0.\u00a0. \u201d Abandon blame.\\nNo sneering: No smirking, eye rolling, sucking teeth. No cutting off or walking away.\\nNo saying, \u201cThat\u2019s stupid, don\u2019t be sad,\u201d \u201cI don\u2019t care what you say.\u201d\\n(Act)Interested\\nListen and appear interested in the other person.\\nListen to the other person\u2019s point of view.\\nFace the person; maintain eye contact; lean toward the person rather than\\naway. Don\u2019t interrupt or talk over the person.\\nBe sensitive to the person\u2019s wish to have the discussion at a later time. Be\\npatient.\\nValidate\\nWith words and actions, show that you understand the other person\u2019s\\nfeelings and thoughts about the situation. See the world from the other person\u2019s\\npoint of view, and then say or act on what you see.\\n\u201cI realize this is hard for you, and .\u00a0.\u00a0. \u201d, \u201cI see that you are busy, and .\u00a0.\u00a0. \u201d\\nGo to a private place when the person is uncomfortable talking in a public\\nplace.\\n(Use an)\\nEasy manner\\nUse a little humor.\\nSmile. Ease the person along. Be light-hearted. Sweet-talk.\\nUse a \u201csoft sell\u201d over a \u201chard sell.\u201d Be \u201cpolitical.\u201d\\nLeave your attitude at the door.\\nOther ideas:\",\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/interpersonal_effectiveness/handouts/interpersonal_effectiveness_handout_6_guidelines_for_relationship_effectiveness_keeping_the_relationship_giv.json\",\"ourspace_shared_life_filter\":{\"revision_id\":\"ourspace_shared_life_filter_v1\",\"title\":\"Guidelines for Relationship Effectiveness: Keeping the Relationship (GIVE) A way to remember these skills is to remember the word GIVE (DEAR MAN, GIVE): (Be) Gentle\",\"domain\":\"interpersonal_effectiveness\",\"item_type\":\"handout\",\"shared_facing_summary\":\"Use this to protect both people: needs are real, boundaries are kind, and a pause is not abandonment when repair is named.\",\"tiny_steps\":[\"Name the ask in one sentence.\",\"Name capacity honestly.\",\"Offer one smaller option.\",\"Agree on a return time or next check-in.\"],\"flare_day_versions\":{\"minimum\":\"One breath, one label, one safe message, or one checkbox.\",\"medium\":\"Two to five minutes with everything reachable from bed/chair.\",\"full\":\"Use the original worksheet/handout when both bodies and brains have capacity.\"},\"accessibility_modifications\":[\"Add reassurance before hard asks.\",\"Use text/chat if speech is hard.\",\"Include caregiver capacity as part of the plan, not an afterthought.\"],\"relationship_and_caregiver_notes\":[\"William's needs and Jasper's capacity both count.\",\"Ask before helping; ask before escalating; name the smallest next step.\",\"Pause means pause, not abandonment. I am coming back. I care about us. I need a smaller next step.\",\"What is needed, what capacity exists, what can be smaller, and what can wait?\"],\"identity_and_trauma_filter\":[\"Use William's masculine language and Jasper's they/them language.\",\"Use consent-based, non-shaming, body-neutral language unless a person has explicitly chosen a term.\",\"Do not turn symptoms, dysphoria, trauma responses, clutter, fatigue, or emotional intensity into moral failure.\"],\"avoid_or_adjust\":[\"Do not use skills to win, corner, threaten leaving, or make either person prove pain or disability.\"],\"suggested_cadence\":[\"as_needed\",\"weekly_repair_check\"],\"app_tags\":[\"adhd_friendly\",\"disability_first\",\"interpersonal_effectiveness\",\"shared\",\"tiny_steps\",\"trauma_informed\"]},\"ourspace_shared_revision_metadata\":{\"source_path\":\"DBT+ADHD Skill Files/03_DBT_Interpersonal_Effectiveness/handouts/json/interpersonal_effectiveness_handout_6_guidelines_for_relationship_effectiveness_keeping_the_relationship_giv.json\",\"shared_output_path\":\"shared/03_dbt_interpersonal_effectiveness/handouts_json/interpersonal_effectiveness_handout_6_guidelines_for_relationship_effecti_1826b8de.json\",\"revised_at_utc\":\"2026-06-26T00:24:16Z\",\"copyright_note\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\"},\"shared_json_path\":\"shared/03_dbt_interpersonal_effectiveness/handouts_json/interpersonal_effectiveness_handout_6_guidelines_for_relationship_effecti_1826b8de.json\"}");
